INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('spitaeler-niederoesterreich-rechnungshof-aerzte-teilzeit-gastpatienten','Spitäler in Niederösterreich: Rechnungshof fordert Reformen','Weniger stationäre Aufenthalte, aber deutlich höhere Kosten: Der Rechnungshof hat die ärztliche Versorgung in Niederösterreichs Spitälern geprüft und empfiehlt Reformen bei Gehältern, Teilzeit und Gastpatienten.','Die Spitäler in Niederösterreich stehen im Mittelpunkt eines neuen Berichts des Rechnungshofs (RH) zur ärztlichen Versorgung in Krankenanstalten. Die Prüfer zeichnen ein Bild, das für ganz Österreich gilt: Es werden weniger Menschen stationär aufgenommen, die Kosten steigen aber kräftig. Gleichzeitig wird es vor allem für kleinere Häuser schwieriger, ärztliche Stellen nachzubesetzen. Der Bericht wurde am Freitag veröffentlicht, wie der ORF Niederösterreich berichtet.

## Weniger Patienten, deutlich höhere Kosten

Laut RH ist die Zahl der stationären Aufenthalte in Österreich zwischen 2014 und 2024 um 22 Prozent gesunken. Im selben Zeitraum sind die Kosten der Krankenanstalten um 71 Prozent gestiegen. Insgesamt wurden 2024 rund 39,5 Milliarden Euro für das Gesundheitswesen ausgegeben. Im EU-Vergleich seien die öffentlichen Gesundheitsausgaben hoch, hält der Rechnungshof fest. Personal und Geld müssten daher effizienter eingesetzt werden, gerade weil Fachkräfte knapp sind.

Einen Kostentreiber sieht der RH im Wettbewerb der Bundesländer um Ärztinnen und Ärzte. Die Länder versuchen, sich gegenseitig mit Gehaltserhöhungen zu überbieten. Das macht Stellen attraktiver, erhöht aber die Gesamtkosten der Spitäler.

## Spitäler Niederösterreich: Teilzeit und Nebenjobs

Für die Spitäler in Niederösterreich nennt der Bericht konkrete Entwicklungen beim ärztlichen Personal:

- Die Teilzeitquote bei Ärztinnen und Ärzten stieg von 2019 bis 2024 von 26 auf 32 Prozent.
- Rund zwei Drittel der Ärzte im Alter zwischen 51 und 60 Jahren meldeten eine Nebenbeschäftigung.
- Kleinere, nicht zentral gelegene Krankenhäuser haben Probleme, Stellen in bestimmten Sonderfächern zu besetzen, und verzeichneten Personalrückgänge.

Der RH empfiehlt, Teilzeitanträge ohne Rechtsanspruch künftig genauer zu prüfen. Dabei soll geklärt werden, ob berücksichtigungswürdige Gründe vorliegen und ob wichtige dienstliche Interessen dagegen sprechen.

Die Spitalsstandorte selbst hat das Land laut Bericht wegen politischer Zusagen nicht in Frage gestellt. Den im März 2025 vom Landtag beschlossenen **Gesundheitsplan 2040+** beurteilt der Rechnungshof grundsätzlich positiv.

## Gastpatienten: Seit Jahren keine Lösung

Ein Dauerthema bleibt die Behandlung von Niederösterreicherinnen und Niederösterreichern in Wien. Zwischen 2018 und 2024 entfielen im Schnitt rund 70.500 stationäre Aufenthalte pro Jahr in Wiener Spitälern auf Personen mit Wohnsitz in Niederösterreich. Das entspricht konstant 16 bis 17 Prozent aller stationären Aufenthalte in der Bundeshauptstadt.

Eine allgemein akzeptierte Grundlage für die länderübergreifende Finanzierung solcher Gastpatienten fehlt bis heute. Der RH hatte dem Gesundheitsministerium das bereits 2015 und 2018 empfohlen. Zwischen Niederösterreich und Wien laufen Gespräche. Dass bilaterale Lösungen möglich sind, zeigen bestehende Vereinbarungen der Steiermark mit Oberösterreich und Salzburg.

## Die Empfehlungen im Überblick

1. Bund und Länder sollen sich auf ein österreichweit abgestimmtes Vorgehen bei ärztlichen Gehaltsmodellen einigen.
2. Für Gastpatienten soll eine gemeinsame Finanzierungsgrundlage geschaffen werden.
3. Mit überregionalen Steuerungsinstrumenten soll der Bedarf an Fachärzten je Sonderfach ermittelt werden, um daraus Ausbildungsplätze abzuleiten.
4. Bund, Länder und Sozialversicherung sollen gemeinsam planen, damit Ausbildungsstellen dort entstehen, wo sie gebraucht werden.

## Reaktionen aus der Politik

Die ÖVP Niederösterreich sieht im Bericht eine Bestätigung des Landeskurses. Ihr Rechnungshofsprecher Harald Servus sprach von einem klaren Plan für eine moderne und leistbare Spitalsversorgung und forderte eine verlässliche Finanzierung für die Ostregion. Patientinnen und Patienten dürften nicht an der Landesgrenze aufgehalten werden.','gesundheit','Medizin','niederoesterreich','news','Presseinfo Redaktion','/assets/img/artikel/spitaeler-niederoesterreich-rechnungshof-aerzte-teilzeit-gastpatienten.webp','ORF Niederösterreich / Rechnungshof','https://noe.orf.at/stories/3380296/','published','2026-11-22T06:55:00.000Z','2026-11-22T06:44:15.831Z','Spitäler Niederösterreich: Rechnungshof-Bericht 2026','Spitäler in Niederösterreich: Der Rechnungshof sieht weniger Patienten, aber 71 % höhere Kosten. Was er zu Ärzte-Teilzeit und Gastpatienten empfiehlt.','Spitäler Niederösterreich','["Spitäler Niederösterreich","Rechnungshof Spitäler","Rechnungshof Bericht Krankenanstalten","Gastpatienten Wien Niederösterreich","Ärzte Teilzeit Niederösterreich","Gesundheitsplan 2040+","Spitalskosten Österreich","ärztliche Versorgung Krankenanstalten"]','Gang in einem Spital in Niederösterreich – Rechnungshof prüft ärztliche Versorgung','Empty modern hospital corridor in a regional Austrian hospital in Lower Austria, early morning light through large windows, hospital beds parked along the wall, a doctor''s white coat on a hook, calm atmosphere, photorealistic, no people, no text, no logos, no readable signs','[{"q":"Was kritisiert der Rechnungshof an den Spitälern in Niederösterreich?","a":"Steigende Kosten trotz weniger Patienten, eine wachsende Teilzeitquote bei Ärzten und Probleme kleinerer Häuser, Facharztstellen nachzubesetzen."},{"q":"Wie viele Niederösterreicher werden in Wiener Spitälern behandelt?","a":"Zwischen 2018 und 2024 im Schnitt rund 70.500 stationäre Aufenthalte pro Jahr, das sind 16 bis 17 Prozent aller Aufenthalte in Wien."},{"q":"Was empfiehlt der Rechnungshof?","a":"Abgestimmte Gehaltsmodelle, eine Finanzierungsgrundlage für Gastpatienten, strengere Prüfung von Teilzeitanträgen und eine bedarfsgerechte Facharztausbildung."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
